import {Leaf,LayoutDashboard,BookOpen,Refrigerator,ShoppingBasket,Inbox,Plus,ArrowUpRight,ArrowRight,Search,ChevronRight,Clock,Users,Check,X,Camera,Link as LinkIcon,ClipboardList,Sparkles,RefreshCw,SlidersHorizontal,Trash2,Pencil,Minus,CheckCheck,ChefHat,Upload,Copy,ExternalLink,AlertCircle,Package,Flame,LogOut,Download} from 'lucide-react';
